fn largest_divisor(n: i8) -> i8 {
    // Since n > 1, we start checking from n/2 downwards
    let start = n / 2;
    
    for d in (1..=start).rev() {
        if n % d == 0 {
            return d;
        }
    }
    
    // If no divisor found in the loop (shouldn't happen for n > 1),
    // return 1 as the fallback
    1
}